    self.fieldOfView = 12
end

function TakeoutVipOrderDialog:__delete()
    self.controller = nil
    self.animator = nil
    self.data = nil
    self.EventEveryThingChangeEventName = nil
end

function TakeoutVipOrderDialog:Awake()
    local cam = UIModule.RootCanvas.defaultCamera
    if not cam then
        return
    end
    self.isOrthographic = cam.orthographic
    if not self.isOrthographic then
        ---如果是透视相机情况下给一个初始的fov值
        self.fieldOfView = cam.fieldOfView
    end
    self.animator = kTool.GetComponent(self.Container.gameObject, typeof(Animator))
    local BtnRank = self.BtnStore.transform.parent:Find("BtnRank")
    SetButtonAction(self.BtnStore, function()
        ---打开商店的逻辑
        ---@type GroceryUtils
        local GroceryUtils = import('Game.Grocery.GroceryUtils')
        ---@type GroceryConstants
        local GroceryConstants = import('Game.Grocery.GroceryConstants')
        local ids = {}--{{id = Constants.UITypeIds.TakeoutVipOrderDialog}}
        GroceryUtils.OpenGroceryStore(GroceryConstants.GroceryType.Tip, ids)
    end)

    if BtnRank then
        SetButtonAction(BtnRank, function()
            ---排行榜的逻辑显示
            UIModule.OpenDialog( UIArgs(Constants.UITypeIds.UIMaidCoffeeCattyRank, {type = MaidCoffeeConstants.CoffeeRankType.CafeTipRank}))
        end)
    end

    self.EventEveryThingChangeEventName = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.OnEveryThingChangeEventName))
end

function TakeoutVipOrderDialog:OnFocus(focus)
    if focus then
        CfUtils.SetCanvasEnabled(self.controller.gameObject, true)
        --local goods = GameUtils.GetTopGoodsId(self.controller.Argument.id)
        --if not string.isEmpty(goods) then
        --    GameUtils.UpdateNavBarShowGoods(goods, false)
        --end
