end

function TakeoutVipOrderDialog:RemoveListener()
    Events.RemoveListener(Constants.EventNames.EveryThingChangeEventName, self.EventEveryThingChangeEventName)
    self.EventEveryThingChangeEventName = nil
end

function TakeoutVipOrderDialog:OnEveryThingChangeEventName(id)
    if not isNull(id) then
        return
    end
    self:FreshUI()
end

function TakeoutVipOrderDialog:OnRewardWindowClose(rewards)
    ---执行下离开的动画，再请求
    UIRaycastBlocker:AddCondition("OnRewardWindowClose")
    try(function()
        --播退场动画
        cs_coroutine.start(function()
            local isFinish = false
            GameUtils.Request(Interfaces.MaidCoffeeTakeoutVipOrderHome, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    ---@type VipOrderDojo
                    local dojo = VipOrderDojo.New()
                    dojo:FillData(checkTable(response.data))
                    ---@type MaidCoffeePlayerComponent
                    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                    maidCoffeePlayerComponent:FreshVipOrderTime(dojo.refreshTime, dojo.id)
                    self.data = dojo
                    isFinish = true
                end
            end)
            while not isFinish do
                cs_coroutine.yield_return()
            end
            ---@type UnityEngine.Animator
            local animator = self.animator
            animator:SetBool(ORDER_ANIM_STATES.ORDER_OUT, true)
            ---开启一个协程
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2.5))
            ---去除消耗
            local isClosed = false
            if #rewards > 0 then
                UIRaycastBlocker:RemoveCondition("OnRewardWindowClose")
                UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = rewards, cb = function()
                                ---回调
                                isClosed = true
                            end }
                        }
                )
            else
                isClosed = true
            end
            while not isClosed do
                cs_coroutine.yield_return()
            end
            UIRaycastBlocker:AddCondition("OnRewardWindowClose")
            animator:SetBool(ORDER_ANIM_STATES.ORDER_OUT_TO_NEXT_ORDER, true)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.45))
            ----刷新下一单的数据
            ---@type TakeoutVipOrderNext
            local env = CfUtils.GetLuaScr(self.AfterStart.gameObject, TakeoutVipOrderNext)
            env:FreshUI(self.data, Bind(self, self.OnFreshOrder))
            UIRaycastBlocker:RemoveCondition("OnRewardWindowClose")
            --print('------>>>NEXT_ORDER_ENTRY')
        end)
    end, function()
        UIRaycastBlocker:RemoveCondition("OnRewardWindowClose")
    end)
end

function TakeoutVipOrderDialog:SwitchToOrder()
    UIRaycastBlocker:AddCondition("OnRewardWindowClose")
    try(function()
        --播退场动画
        cs_coroutine.start(function()
            ---@type UnityEngine.Animator
            local animator = self.animator
            animator:SetBool(ORDER_ANIM_STATES.NEXT_ORDER_OUT, true)
            print('------>>>SwitchToOrder')
            ---开启一个协程
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
            animator:SetBool(ORDER_ANIM_STATES.NEXT_ORDER_TO_ENTRY, true)
            ---开启一个协程
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.45))
            ---@type TakeoutVipOrderStart
            local env = CfUtils.GetLuaScr(self.BeforeStart.gameObject, TakeoutVipOrderStart)
            env:FreshUI(self.data, Bind(self, self.OnStartCar))
            UIRaycastBlocker:RemoveCondition("OnRewardWindowClose")
            -----@type UnityEngine.Animator
            --local animator = self.animator
            --animator:SetBool(ORDER_ANIM_STATES.ORDER_ENTRY, true)
        end)
    end, function()
        UIRaycastBlocker:RemoveCondition("OnRewardWindowClose")
    end)
end

---OnFreshOrder
---刷新订单
function TakeoutVipOrderDialog:OnFreshOrder(data, type)
    if type == 1 then
        ---正常倒计时完成
        self.data = data
        self:SwitchToOrder()
    else
        ---@type TableML.TableFile
        local tableFile = SettingMgr:GetInstance():Get(AutoIds.IdSetting3054)
        ---@type TableML.TableFileRow
        local tableFileRow = tableFile:GetByPrimaryKey(data.id)
        if isNull(tableFileRow) then
            return
        end
        local time = checkNumber(data.refreshTime)
        local timeDelta = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.VipOrderTimeDelta).num)
        local fastId = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.VipOrderConsumeId).num)
        local num = checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(MaidCoffeeConstants.ParamsIds.VipOrderConsumeNum).num)
        local fastNum = num_floor(time / timeDelta) * num
        if time <= timeDelta then
            fastNum = num
        end
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(fastId)
        local haveNo = GoodsUtils.GetThingNo(fastId)
        print('--->>', fastId, fastNum, haveNo)

        local function FreshOrder()
            UIRaycastBlocker:AddCondition("OnRewardWindowClose")
            try(function()
                --播退场动画
                cs_coroutine.start(function()
                    local isFinish = false
                    GameUtils.Request(Interfaces.MaidCoffeeTakeoutVipOrderRefresh, {}, function(request, response)
                        if checkNumber(response.errCode) == 0 then
                            self.data.refreshTime = 0
                            self.data.status = 1
                            ---@type MaidCoffeePlayerComponent
                            local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                            maidCoffeePlayerComponent:FreshVipOrderTime(0, self.data.id)
                            ---@type TakeoutVipOrderNext
                            local env = CfUtils.GetLuaScr(self.AfterStart.gameObject, TakeoutVipOrderNext)
                            env:DeleteTimer()
                            GoodsUtils.DrawRewards({ { goodsId = fastId, num = -fastNum } })
                            isFinish = true
                        end
                    end)
                    while not isFinish do
                        cs_coroutine.yield_return()
                    end
                    ---@type UnityEngine.Animator
                    local animator = self.animator
                    animator:SetBool(ORDER_ANIM_STATES.NEXT_ORDER_OUT, true)
                    ---开启一个协程
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
                    animator:SetBool(ORDER_ANIM_STATES.NEXT_ORDER_TO_ENTRY, true)
                    ---开启一个协程
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.45))
                    ---@type TakeoutVipOrderStart
                    local env = CfUtils.GetLuaScr(self.BeforeStart.gameObject, TakeoutVipOrderStart)
                    env:FreshUI(self.data, Bind(self, self.OnStartCar))
                    UIRaycastBlocker:RemoveCondition("OnRewardWindowClose")
                    -----@type UnityEngine.Animator
                    --local animator = self.animator
                    --animator:SetBool(ORDER_ANIM_STATES.ORDER_ENTRY, true)
                end)
            end, function()
                UIRaycastBlocker:RemoveCondition("OnRewardWindowClose")
            end)
        end
        if fastNum == 0 then
            FreshOrder()
            return
        end
        GameUtils.SecondConfirm(localize('是否使用_num_个_name_立即刷新', { _num_ = fastNum, _name_ = goodsVo.name }), function()
            if haveNo < fastNum then
                GoodsUtils.CheckCurrencyConsume({goodsId = fastId, num = fastNum} , FreshOrder)
                return
            end
            FreshOrder()
        end)
    end
end

---OnStartCar
---开始发车的逻辑
function TakeoutVipOrderDialog:OnStartCar()
    ---@type TakeoutVipOrderStart
    local env = CfUtils.GetLuaScr(self.BeforeStart.gameObject, TakeoutVipOrderStart)
    local canTrack = env:CanStartTrack()
    if canTrack == 1 then
        local isFinalFish = env:IsFinalFishTrack()
        if isFinalFish == 0 then
            ----鱼王未提交
            GameUtils.SecondConfirm(localize('当前流浪猫想要的小鱼干还没有提交，是否确认发车？'), function()
                GameUtils.Request(Interfaces.MaidCoffeeTakeoutVipOrderStartCar, {}, function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        ---去除消耗
                        local rewards = checkTable(response.data.rewards)
                        if #rewards > 0 then
                            GoodsUtils.DrawRewards(rewards, true)
                            self:OnRewardWindowClose(rewards)
                        end
                    end
                end)
            end)
        else
            GameUtils.Request(Interfaces.MaidCoffeeTakeoutVipOrderStartCar, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    ---去除消耗
                    local rewards = checkTable(response.data.rewards)
                    if #rewards > 0 then
                        GoodsUtils.DrawRewards(rewards, true)
                        self:OnRewardWindowClose(rewards)
                    end
                end
            end)
        end
    else
        GameUtils.Toast(localize('装车后才能发车'))
    end
end

function TakeoutVipOrderDialog:FreshUI()
    if checkNumber(self.data.status) == Status.IDLE then
        ---@type TakeoutVipOrderStart
        local env = CfUtils.GetLuaScr(self.BeforeStart.gameObject, TakeoutVipOrderStart)
        env:FreshUI(self.data, Bind(self, self.OnStartCar))
    else
        ---@type TakeoutVipOrderNext
        local env = CfUtils.GetLuaScr(self.AfterStart.gameObject, TakeoutVipOrderNext)
        env:FreshUI(self.data, Bind(self, self.OnFreshOrder))
    end
end

function TakeoutVipOrderDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if checkNumber(self.data.status) == Status.IDLE then
            ---@type TakeoutVipOrderStart
            local env = CfUtils.GetLuaScr(self.BeforeStart.gameObject, TakeoutVipOrderStart)
            env:FreshUI(self.data, Bind(self, self.OnStartCar))
            ---@type UnityEngine.Animator
            local animator = self.animator
            animator:SetBool(ORDER_ANIM_STATES.ORDER_ENTRY, true)
        else
            ---下一订单预览的逻辑
            ---@type UnityEngine.Animator
            local animator = self.animator
            animator:SetBool(ORDER_ANIM_STATES.NEXT_ORDER_ENTRY, true)
            ---@type TakeoutVipOrderNext
            local env = CfUtils.GetLuaScr(self.AfterStart.gameObject, TakeoutVipOrderNext)
            env:FreshUI(self.data, Bind(self, self.OnFreshOrder))
        end
        ---刷新商城按钮的卡牌信息
        if checkNumber(self.data.mallCardId) == 0 then
            self.data.mallCardId = 102011
        end
        if checkNumber(self.data.mallCardId) > 0 then
            local cardConfMgr = CardConfMgr:GetInstance()
            local cardImageTrans = self.BtnStore.transform:Find("ImgCardIconMask/ImgCardIcon")
            ---@type CardVo
            local cardVo = cardConfMgr:GetCardByRefId(self.data.mallCardId)
            ---CardUtils.GetCardCareerIconPath(cardVo.career, true, true)
            local skinId = cardVo.defaultSkin
            ---@type CardSkinVo
            local skinVo = cardConfMgr:GetCardSkinBySkinId(skinId)
            if skinVo then
                local rare = cardVo.rare
                local rareBgTrans = self.BtnStore.transform:Find("BtnRoleNameNode/AnimRoot/Rare/ImgRareBgMask/ImgRareBg")
                local ImgRareIconTrans = self.BtnStore.transform:Find("BtnRoleNameNode/AnimRoot/Rare/Node/ImgRareIcon")
                local ImgRareIconTrans2 = self.BtnStore.transform:Find("BtnRoleNameNode/AnimRoot/Rare/Node/ImgRareIcon2")
                ---刷新背景
                CfUtils.SetUISwitchImage(rareBgTrans, rare)
                CfUtils.SetUISwitchImage(ImgRareIconTrans, rare)
                CfUtils.SetUISwitchImage(ImgRareIconTrans2, rare)
                ---更新头象图标
                CfUtils.FillImage(cardImageTrans, skinVo.cardHeadList)
            end
        end
    end))
    return coWait
end

