function TakeoutVipOrderDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.SetUICameraProjection(self.isOrthographic, self.fieldOfView)
        self:RemoveListener()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

